def canon(mask):
 a=np.array([[int(x) for x in row] for row in mask])
 forms=[]
 for k in range(4):
  z=np.rot90(a,k)
  for x in (z,np.fliplr(z)):
   coords=np.argwhere(x); x=x[coords[:,0].min():coords[:,0].max()+1,coords[:,1].min():coords[:,1].max()+1]
   forms.append(tuple(''.join(map(str,row)) for row in x))
 return min(forms)
